import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.qCVWde4n.js";const k=JSON.parse('{"title":"网页控制台：你的模型、你的 key、你的套餐","description":"","frontmatter":{},"headers":[],"relativePath":"zh/web.md","filePath":"zh/web.md"}'),s={name:"zh/web.md"};function i(r,e,n,c,h,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="网页控制台-你的模型、你的-key、你的套餐" tabindex="-1">网页控制台：你的模型、你的 key、你的套餐 <a class="header-anchor" href="#网页控制台-你的模型、你的-key、你的套餐" aria-label="Permalink to &quot;网页控制台：你的模型、你的 key、你的套餐&quot;">​</a></h1><blockquote><p>网页控制台是 <code>nanomuse serve</code> 在 <code>/</code> 上托管的那个应用——桌面版和自己部署的运行时的大门（<a href="./app">app.md</a>）。这一页只讲它的一部分：它怎么挑选回答的模型，以及模型缺了什么时它给出什么。做一把 key 的指南在 <a href="./own-key">own-key.md</a>。</p></blockquote><h2 id="one-catalogue" tabindex="-1">一份目录 <a class="header-anchor" href="#one-catalogue" aria-label="Permalink to &quot;一份目录 {#one-catalogue}&quot;">​</a></h2><p>控制台读的服务商列表和手机、桌面版、中继是同一份：<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/llm/providers.json" target="_blank" rel="noreferrer"><code>nanomuse/llm/providers.json</code></a>（约定 C11）。每个服务商写明一把 key 在那里能覆盖什么——<code>chat</code>、<code>vision</code>（手看截图）、<code>image</code>（形象工作室的图片）、<code>video</code>（它的短视频）——以及除了 key 之外还有哪些登录方式。控制台先问运行时（<code>GET /api/providers</code>，它还会说今天配置了哪些位置、各覆盖什么），在旧版运行时上退回构建时打包的那份副本，这时对配置了什么一无所知。模块是 <code>web/src/providers.ts</code>；<code>web/src/providers.test.ts</code> 检查排序、映射和那些句子。</p><h2 id="where-it-shows" tabindex="-1">显示在哪里 <a class="header-anchor" href="#where-it-shows" aria-label="Permalink to &quot;显示在哪里 {#where-it-shows}&quot;">​</a></h2><p><strong>连接 → 对话模型。</strong> 服务商卡片是运行时的预设，所在地区的首选排第一（中国大陆是阿里云百炼，其他地方是 OpenRouter——<a href="https://github.com/nano-muse/nanoMuse/blob/main/web/src/region.ts" target="_blank" rel="noreferrer">region.ts</a>）。卡片下面是所选服务商在目录里的那一行：它的 key 覆盖什么，以及需要知道的事（Kimi 的几个版本、OpenRouter 的 Image API、ChatGPT 的注意事项）。「动手模型」选择器列出能看图的模型；没有 <code>vision</code> 的服务商得到的是那一句话，而不是一个看不见的动手模型。在「图片与短片」下，没有 <code>image</code> 或 <code>video</code> 的服务商在选择器的位置显示那句话；有的话则显示「自动——目录的默认值」，让你知道「自动」会用什么来画。</p><p><strong>连接 → 或者用 ChatGPT 套餐登录。</strong> 这张卡片让运行时启动 Codex 登录（<code>POST /api/chatgpt/login</code> → <code>{url}</code>），在新标签页打开那个页面，每两秒轮询一次 <code>GET /api/chatgpt/status</code>，最多十分钟，令牌进了运行时的存储之后，提供「让它来回答对话」（<code>[llm] provider = &quot;chatgpt&quot;</code>）和「退出 ChatGPT」（<code>POST /api/chatgpt/logout</code>）。卡片写明这个登录覆盖什么——对话和手，不包括图片和短视频——并带着关于 OpenAI 条款的那句实话。没有这些路由的运行时回答 404；这时卡片直接给出要在终端里跑的命令 <code>nanomuse chatgpt login</code>，而不是装作能行。登录的回调落在运行时所在机器的 1455 端口。浏览器够不到它时（运行时在另一台电脑上，或者端口被占——登录回答里 <code>port_bound: false</code>），浏览器最后会停在一个打不开的地址上；卡片有一个输入框接收这个地址，再交给运行时（<code>POST /api/chatgpt/callback {url}</code>；过期的链接是 400 <code>state_mismatch</code>，超过十分钟的登录是 409 <code>no_login</code>）。这个输入框任何情况下都在，端口绑不上时会多一句话说明原因（<a href="./configuration#a-chatgpt-plan-instead-of-a-key">configuration.md</a>）。</p><p><strong>额度卡片</strong>（在「账号」里，以及聊天里出现 <code>allowance_exhausted</code> 时）给出三条路：「换成自己的 key」，带所在地区的首选、一个打开「连接」并定位到该服务商的「设置一下」、「到 … 获取密钥」、指南，以及「其他服务商，以及各自的 key 能做什么」下面地区列表里的其余服务商（中继发来 <code>guidance.providers</code> 时用中继的，中继 0.21；否则用目录的），每一个都带自己的覆盖说明、自己的「设置一下」和 key 链接；「用你已经在付费的套餐登录」，ChatGPT 卡片就嵌在里面；还有邀请。80 % 的提前提醒和第一次登录的面板指向同一个地方。</p><p><strong>形象工作室。</strong> 没有图像模型时，「画」按钮不可用，下面那一行就是那一句话——中国大陆是「画图需要一个有图像模型的服务商——阿里云百炼、智谱 GLM、硅基流动或火山方舟」，其他地方是「OpenRouter、OpenAI、Google Gemini 或 xAI Grok」——旁边是「更换」。<strong>设置 → 图像与视频模型</strong>在运行时说图片或短视频没有覆盖时，把同一句话显示为它的值。</p><h2 id="the-sentences" tabindex="-1">那些句子 <a class="header-anchor" href="#the-sentences" aria-label="Permalink to &quot;那些句子 {#the-sentences}&quot;">​</a></h2><p>每个不可用的功能都是一句话，从不是原始错误，由 <code>unavailableLine(cap, region, locale)</code> 根据所在地区具备该能力的服务商生成（最多四个，按目录顺序）：</p><table tabindex="0"><thead><tr><th>能力</th><th>English</th><th>中文</th></tr></thead><tbody><tr><td><code>image</code></td><td>Pictures need a provider with image models — {providers}.</td><td>画图需要一个有图像模型的服务商——{providers}。</td></tr><tr><td><code>video</code></td><td>Clips need a provider with video models — {providers}.</td><td>生成视频需要一个有视频模型的服务商——{providers}。</td></tr><tr><td><code>vision</code></td><td>The hands need a model that sees pictures — {providers}.</td><td>动手需要一个能看图的模型——{providers}。</td></tr><tr><td><code>chat</code></td><td>Chat needs a model — {providers}.</td><td>对话需要一个模型——{providers}。</td></tr></tbody></table><p>每句旁边有一个「怎么做」链接，指向 <a href="./own-key">own-key.md</a>。服务商的名字按控制台的语言取自目录（<code>name</code> / <code>name_zh</code>）。</p><p><strong>中继拒绝的一个回合</strong>也是一句话，按中继的 <code>code</code> 来（<code>nanomuse/server/failures.py</code>；这句话就是 <code>web/src/i18n/zh-CN.ts</code> 里的键，所以中文是从英文查出来的）：额度用完（下面带那张几条路的卡片）、每日上限、限流、key 无效、账号被停用、中继不提供的模型、中继背后的服务商出了问题——以及从 0.1.40 起，原来落到「模型服务商返回了一个错误：…」的那四种，和运营者的开关发出的那五种（<a href="./cloud#controls">cloud.md</a>）：</p><table tabindex="0"><thead><tr><th>中继说</th><th>聊天里显示</th></tr></thead><tbody><tr><td><code>413 too_large</code></td><td>这条消息超出了模型的上下文窗口。精简一下、去掉部分附件，或者开一个新对话。</td></tr><tr><td><code>403 not_invited</code></td><td>这个中继只接受邀请注册；在「账号」里用邀请码登录。</td></tr><tr><td><code>429 too_many_in_flight</code></td><td>这个账号同时进行的对话太多了，等一轮结束后再试。</td></tr><tr><td><code>429 provider_busy</code></td><td>模型服务商正忙，稍后再试。</td></tr><tr><td><code>429 allowance_exhausted</code> 且 <code>paused: true</code></td><td>这个中继暂时停发了免费额度，不是用完了。在「连接」里填上你自己的模型 key 就能继续；你的登录、设备和剩余额度都保持原样。——和额度用完时同一张几条路的卡片，通知带着 <code>paused</code></td></tr><tr><td><code>403 signup_closed</code></td><td>这个中继暂时停止了新注册，已有账号照常使用。稍后再试。</td></tr><tr><td><code>503 service_paused</code></td><td>nanoMuse Cloud 被运营者暂时停用了，你的登录和数据都保留着。稍后再试。</td></tr><tr><td><code>503 sync_paused</code></td><td>这个中继暂时停止了对话同步，已存的内容保留着，各设备各自继续使用。</td></tr><tr><td><code>503 hub_paused</code></td><td>这个中继暂时停止了设备互联，各设备各自继续使用。</td></tr></tbody></table><p>原始回复留在「详情」下面，供提 bug 时用，从不作为唯一显示的内容。</p><h2 id="checks" tabindex="-1">检查 <a class="header-anchor" href="#checks" aria-label="Permalink to &quot;检查 {#checks}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; LANG</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">en_US.UTF-8</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>构建会写出 <code>nanomuse/server/static/</code>，它随改动一起提交；<code>web/tsconfig.tsbuildinfo</code> 是副产物，不提交。</p>',19)])])}const u=t(s,[["render",i]]);export{k as __pageData,u as default};
